#!/usr/bin/env bash
# Chapter 03, MnM: matching and merging. The event of the book is a leading-order 2 -> 2 process (q qbar -> b bbar)
# generated by Pythia8 alone, with no external matrix-element generator and no extra-jet samples to combine, so there
# is nothing to match or merge: the stage exists in the journey (it is where MLM / CKKW-L / FxFx would act on an LHE
# input) but it is empty here. This script does not run any cmsRun. It verifies in the configuration and the Pythia8
# banner of chapter 02 that no matching / merging is configured, writes that check to the log, and links the output of
# chapter 02 as the output of this chapter so that the chain of Rule E is unbroken.
# Output in test/03_MnM/out/: mnm_03_MnM.log (the check), step1_GEN_03_MnM.root -> ../../02_PS/out/step1_GEN_02_PS.root
set -euo pipefail
CHAPTER=03_MnM
source "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")/../common/jitjet_common.sh"
jitjet_init
in=$(jitjet_prev 02_PS step1_GEN_02_PS.root)
cfg=$TEST/02_PS/step1_GEN_02_PS_cfg.py
log=$TEST/02_PS/out/step1_GEN_02_PS.log
{
  echo "== Chapter 03 MnM, $(date '+%Y-%m-%d %H:%M'): is any matching or merging configured for the event of the book?"
  echo "-- generator fragment and Pythia8 parameters of $cfg"
  grep -nE "processParameters|HardQCD|pTHatMin|PartonLevel|HadronLevel|Merging|JetMatching|LHE|UserHooks|ExternalDecays" "$cfg" || true
  echo "-- matching / merging settings in the Pythia8 banner of $log (changed settings are listed by Pythia8)"
  if grep -qiE "Merging:|JetMatching|UserHooks" "$log"; then
    grep -niE "Merging:|JetMatching|UserHooks" "$log"
  else
    echo "   none: no Merging:*, JetMatching or UserHooks setting is active; the MnM stage does nothing to this event"
  fi
  echo "-- the hard process is a single LO 2 -> 2 scattering: number of outgoing hard partons (status 23) in event $EVENT"
  python3 - "$in" "$EVENT" <<'EOF'
import sys
from DataFormats.FWLite import Events, Handle
h = Handle('std::vector<reco::GenParticle>')
for ev in Events(sys.argv[1]):
    a = ev.eventAuxiliary()
    if '%d:%d:%d' % (a.run(), a.luminosityBlock(), a.event()) != sys.argv[2]:
        continue
    ev.getByLabel('genParticles', h)
    out = [p for p in h.product() if p.status() == 23]
    print('   %d outgoing partons of the hard process: %s' % (len(out), ', '.join('pdg %d pT %.1f' % (p.pdgId(), p.pt()) for p in out)))
    break
EOF
  echo "-- output of this chapter = output of chapter 02 (nothing changed): $OUT/step1_GEN_03_MnM.root"
} > "$OUT/mnm_03_MnM.log" 2>&1
ln -sfn "$in" "$OUT/step1_GEN_03_MnM.root"
cat "$OUT/mnm_03_MnM.log"
